// Some portions generated by Claude
import { useCallback, useEffect, useMemo, useState, type Dispatch, type SetStateAction } from "react";
import { FACET_LIST_LIMIT } from "./explorer-config.ts";
import type { EndpointFacetValue, FilterFacet, RangeDraft } from "./explorer-types.ts";
import { formatRangeValue, generatedFacetQuery } from "./facet-queries.ts";
import { mergeFacetValues } from "./facet-values.ts";
import { facetModel, valuesInRange } from "./graph-facets.ts";
import type { GraphEdge, GraphNode } from "./graph-types.ts";
import {
  BLANK_VISUAL,
  facetValueVisual,
  LITERAL_VISUAL,
  LOADING_IRI_VISUAL,
  nodeTypeIds,
  nodeVisual,
  TYPE_PALETTE,
  typeVisual,
  UNTYPED_IRI_TYPE,
} from "./graph-visuals.ts";

export type FilterChip = { facetId: string; valueId: string | null; text: string };

export type DisplayedFacet = FilterFacet & { searchHit: boolean };

export type FacetFilters = ReturnType<typeof useFacetFilters>;

/**
 * The state of the Filters panel and everything derived from it: the filter model over the selectable nodes, the
 * facets as the panel lists them (search, "more filters", repository-wide counts), the active filters as chips, the
 * generated SPARQL of the selection, and the actions the panel and the rest of the explorer use to change it.
 */
export function useFacetFilters(input: {
  /** The selected values per filter; owned by the explorer because undo and storage include it. */
  selection: Map<string, Set<string>>;
  setSelection: Dispatch<SetStateAction<Map<string, Set<string>>>>;
  nodes: readonly GraphNode[];
  edges: readonly GraphEdge[];
  nodeById: ReadonlyMap<string, GraphNode>;
  hiddenPredicates: ReadonlySet<string>;
  /** Called whenever a filter changes, so a hand-made selection gives way to the filters. */
  onChange: () => void;
  /**
   * Whether anything needs the filter model: the panel is open or a filter is active. On a large graph the model
   * costs a pass over every node and edge, so it is not kept up to date while nobody looks at it.
   */
  needed: boolean;
  scope?: string;
}) {
  const { selection, setSelection, nodes, edges, nodeById, hiddenPredicates, onChange, needed } = input;
  // Filters the user opened or closed by hand; the others follow the defaults of the panel.
  const [facetOpen, setFacetOpen] = useState<Map<string, boolean>>(() => new Map());
  const [showAll, setShowAll] = useState(false);
  const [search, setSearch] = useState("");
  // The typed bounds of range filters; they apply while the filter is part of the selection.
  const [rangeDrafts, setRangeDrafts] = useState<Map<string, RangeDraft>>(() => new Map());
  const [repositoryCounts, setRepositoryCounts] = useState<Map<string, EndpointFacetValue[]>>(() => new Map());
  const [countingFacetId, setCountingFacetId] = useState<string | null>(null);

  const model = useMemo(
    () =>
      facetModel({
        nodes: needed ? nodes : [],
        edges: needed ? edges : [],
        nodeById,
        selection,
        typesOf: (node) =>
          nodeTypeIds(node).map((typeId) => node.types?.find((type) => type.id === typeId) ?? UNTYPED_IRI_TYPE),
        hiddenPredicates,
      }),
    [edges, hiddenPredicates, nodeById, nodes, selection, needed],
  );

  const facets = useMemo<FilterFacet[]>(
    () =>
      model.facets.map((facet) => {
        const values = facet.values.map((value) => ({
          ...value,
          visual:
            facet.category === "type"
              ? typeVisual(value.id)
              : facet.category === "kind"
                ? value.id === "literal"
                  ? LITERAL_VISUAL
                  : value.id === "blank"
                    ? BLANK_VISUAL
                    : TYPE_PALETTE[0]
                : facet.category === "predicate"
                  ? value.node
                    ? nodeVisual(value.node)
                    : LOADING_IRI_VISUAL
                  : facetValueVisual(`${facet.category}:${value.id}`),
        }));
        return {
          ...facet,
          values,
          maxCount: Math.max(...values.map((value) => value.count), 1),
          endpointQueryable: facet.category === "type" || facet.category === "predicate",
        };
      }),
    [model.facets],
  );

  // A range keeps selecting the values inside it as values are loaded or hidden.
  useEffect(() => {
    if (!rangeDrafts.size) return;
    setSelection((current) => {
      let next: Map<string, Set<string>> | null = null;
      current.forEach((values, facetId) => {
        const draft = rangeDrafts.get(facetId);
        const facet = model.facets.find((candidate) => candidate.id === facetId);
        if (!draft || !facet?.range) return;
        const ids = valuesInRange(facet, draft.from, draft.to);
        if (ids.size === values.size && [...ids].every((id) => values.has(id))) return;
        next ??= new Map(current);
        if (ids.size) next.set(facetId, ids);
        else next.delete(facetId);
      });
      return next ?? current;
    });
  }, [model.facets, rangeDrafts, setSelection]);

  const activeCount = useMemo(() => [...selection.values()].filter((values) => values.size > 0).length, [selection]);
  const matches = useMemo(() => (activeCount ? model.matches : new Set<string>()), [activeCount, model.matches]);

  const generatedQuery = useMemo(
    () =>
      generatedFacetQuery(selection, {
        wikidata: false,
        scope: input.scope,
        ranges: new Map(
          facets.flatMap((facet) => {
            const draft = rangeDrafts.get(facet.id);
            return facet.range && draft && selection.has(facet.id)
              ? [[facet.id, { kind: facet.range.kind, ...draft }] as const]
              : [];
          }),
        ),
      }),
    [facets, rangeDrafts, selection, input.scope],
  );

  const displayed = useMemo<DisplayedFacet[]>(() => {
    const term = search.trim().toLocaleLowerCase();
    return facets.flatMap((facet) => {
      const counted = repositoryCounts.get(facet.id);
      const values = counted?.length
        ? mergeFacetValues(
            facet.values,
            counted.map((value) => {
              const node = nodeById.get(value.id);
              return { ...value, visual: node ? nodeVisual(node) : LOADING_IRI_VISUAL };
            }),
          )
        : facet.values;
      const nameMatches = !term || facet.label.toLocaleLowerCase().includes(term);
      const shown = nameMatches ? values : values.filter((value) => value.label.toLocaleLowerCase().includes(term));
      if (!nameMatches && !shown.length) return [];
      return [
        {
          ...facet,
          values: shown,
          searchHit: Boolean(term) && !nameMatches,
          maxCount: Math.max(...values.map((value) => value.count), 1),
        },
      ];
    });
  }, [facets, nodeById, repositoryCounts, search]);

  const listed = useMemo(
    () =>
      showAll || search.trim()
        ? displayed
        : displayed.filter((facet, index) => index < FACET_LIST_LIMIT || selection.has(facet.id)),
    [displayed, search, selection, showAll],
  );

  const chips = useMemo(
    () =>
      facets.flatMap((facet): FilterChip[] => {
        const selected = selection.get(facet.id);
        if (!selected?.size) return [];
        const draft = rangeDrafts.get(facet.id);
        if (facet.range && draft) {
          const bound = (text: string, fallback: number) => text.trim() || formatRangeValue(facet.range!.kind, fallback);
          return [
            {
              facetId: facet.id,
              valueId: null,
              text: `${facet.label}: ${bound(draft.from, facet.range.min)} – ${bound(draft.to, facet.range.max)}`,
            },
          ];
        }
        return facet.values
          .filter((value) => selected.has(value.id))
          .map((value) => ({
            facetId: facet.id,
            valueId: value.id,
            text: facet.category === "type" ? value.label : `${facet.label}: ${value.label}`,
          }));
      }),
    [facets, rangeDrafts, selection],
  );

  const clear = useCallback(() => setSelection((current) => (current.size ? new Map() : current)), [setSelection]);

  const toggleValue = useCallback(
    (facetId: string, valueId: string, checked: boolean) => {
      setSelection((current) => {
        const next = new Map(current);
        const values = new Set(next.get(facetId) ?? []);
        if (checked) values.add(valueId);
        else values.delete(valueId);
        if (values.size) next.set(facetId, values);
        else next.delete(facetId);
        return next;
      });
      onChange();
    },
    [onChange, setSelection],
  );

  /** Removes one value of a filter, or the whole filter when `valueId` is null (a range). */
  const removeValue = useCallback(
    (facetId: string, valueId: string | null) => {
      if (valueId !== null) {
        toggleValue(facetId, valueId, false);
        return;
      }
      setSelection((current) => {
        const next = new Map(current);
        next.delete(facetId);
        return next;
      });
    },
    [setSelection, toggleValue],
  );

  const updateRange = useCallback(
    (facet: FilterFacet, bound: keyof RangeDraft, text: string) => {
      const current = selection.has(facet.id) ? rangeDrafts.get(facet.id) : undefined;
      const draft = { from: current?.from ?? "", to: current?.to ?? "", [bound]: text };
      setRangeDrafts((drafts) => new Map(drafts).set(facet.id, draft));
      const ids = valuesInRange(facet, draft.from, draft.to);
      setSelection((previous) => {
        const next = new Map(previous);
        if (ids.size) next.set(facet.id, ids);
        else next.delete(facet.id);
        return next;
      });
      onChange();
    },
    [onChange, rangeDrafts, selection, setSelection],
  );

  /** One type at a time (the legend): a second press clears it. */
  const toggleType = useCallback(
    (facetId: string, typeId: string) => {
      setSelection((current) => {
        const values = current.get(facetId);
        return current.size === 1 && values?.size === 1 && values.has(typeId)
          ? new Map()
          : new Map([[facetId, new Set([typeId])]]);
      });
      onChange();
    },
    [onChange, setSelection],
  );

  const isOnlyType = useCallback(
    (facetId: string, typeId: string) =>
      selection.size === 1 && selection.get(facetId)?.size === 1 && Boolean(selection.get(facetId)?.has(typeId)),
    [selection],
  );

  /** Repository-wide counts of a filter's values; `count` runs the query and returns null when it is stale. */
  const countInRepository = useCallback(
    async (facet: FilterFacet, count: (facet: FilterFacet) => Promise<EndpointFacetValue[] | null>) => {
      setCountingFacetId(facet.id);
      try {
        const values = await count(facet);
        if (values) setRepositoryCounts((current) => new Map(current).set(facet.id, values));
      } finally {
        setCountingFacetId((current) => (current === facet.id ? null : current));
      }
    },
    [],
  );

  const forgetRepositoryCounts = useCallback(
    () => setRepositoryCounts((current) => (current.size ? new Map() : current)),
    [],
  );

  return {
    selection,
    setSelection,
    facetOpen,
    setFacetOpen,
    showAll,
    setShowAll,
    search,
    setSearch,
    rangeDrafts,
    repositoryCounts,
    countingFacetId,
    model,
    facets,
    displayed,
    listed,
    chips,
    activeCount,
    hasActive: activeCount > 0,
    matches,
    generatedQuery,
    clear,
    toggleValue,
    removeValue,
    updateRange,
    toggleType,
    isOnlyType,
    countInRepository,
    forgetRepositoryCounts,
  };
}
